custom_css:
.sc-tw :root{
            color-scheme: dark;
            --amber: oklch(76% 0.15 75);
            --amber-deep: oklch(62% 0.12 68);
            --oak: oklch(63% 0.08 82);
            --concrete: oklch(24% 0.02 240);
            --concrete-2: oklch(18% 0.02 240);
            --graphite: oklch(12% 0.02 240);
            --text: oklch(97% 0.01 80);
        }.sc-tw *{
            box-sizing: border-box;
        }.sc-tw html{
            scroll-behavior: smooth;
        }.sc-tw{
            margin: 0;
            overflow-x: hidden;
            font-family: "Inter Tight", sans-serif;
            color: white;
            background:
                radial-gradient(circle at 20% 10%, rgba(255, 181, 92, .18), transparent 18%),
                radial-gradient(circle at 82% 12%, rgba(255, 255, 255, .04), transparent 14%),
                linear-gradient(180deg, oklch(18% 0.02 240) 0%, oklch(14% 0.02 240) 45%, oklch(10% 0.02 240) 100%);
        }.sc-tw body::before{
            content: "";
            position: fixed;
            inset: 0;
            pointer-events: none;
            background-image:
                linear-gradient(rgba(255, 255, 255, .03) 1px, transparent 1px),
                linear-gradient(90deg, rgba(255, 255, 255, .03) 1px, transparent 1px),
                repeating-linear-gradient(135deg, rgba(255, 255, 255, .03) 0 1px, transparent 1px 12px);
            background-size: 128px 128px, 128px 128px, 240px 240px;
            opacity: .2;
            mask-image: radial-gradient(circle at center, black 34%, transparent 88%);
            z-index: -2;
        }.sc-tw .mono{
            font-family: "IBM Plex Mono", monospace;
        }.sc-tw .serif{
            font-family: "Cormorant Garamond", serif;
            letter-spacing: -.055em;
        }.sc-tw .grain-concrete{
            background:
                linear-gradient(180deg, rgba(255, 255, 255, .05), rgba(255, 255, 255, .015)),
                repeating-linear-gradient(90deg, rgba(255, 255, 255, .02) 0 1px, transparent 1px 10px),
                linear-gradient(180deg, rgba(52, 53, 58, .78), rgba(28, 30, 34, .94));
        }.sc-tw .grain-oak{
            background:
                linear-gradient(180deg, rgba(255, 255, 255, .04), rgba(255, 255, 255, .01)),
                repeating-linear-gradient(90deg, rgba(145, 110, 64, .12) 0 1px, transparent 1px 8px),
                linear-gradient(180deg, rgba(93, 66, 39, .72), rgba(55, 39, 24, .92));
        }.sc-tw .sunset-amber{
            background:
                radial-gradient(circle at 20% 10%, rgba(255, 190, 112, .16), transparent 18%),
                linear-gradient(180deg, rgba(134, 82, 40, .95), rgba(61, 36, 20, .98));
        }.sc-tw .dense-panel{
            background:
                linear-gradient(180deg, rgba(255, 255, 255, .055), rgba(255, 255, 255, .02)),
                linear-gradient(135deg, rgba(255, 255, 255, .04), transparent 35%);
            border: 1px solid rgba(255, 255, 255, .08);
            box-shadow:
                inset 0 1px 0 rgba(255, 255, 255, .06),
                0 24px 70px rgba(0, 0, 0, .28);
            backdrop-filter: blur(20px);
            -webkit-backdrop-filter: blur(20px);
        }.sc-tw .amber-button{
            position: relative;
            overflow: hidden;
            border-radius: 1rem;
            background:
                linear-gradient(180deg, rgba(255, 196, 116, .96), rgba(193, 124, 47, .92));
            border: 1px solid rgba(255, 255, 255, .14);
            color: #1d130a;
            box-shadow:
                inset 0 1px 0 rgba(255, 255, 255, .45),
                0 24px 50px rgba(0, 0, 0, .26);
            transition: transform .45s cubic-bezier(.16, 1, .3, 1), box-shadow .45s ease;
        }.sc-tw .amber-button::before{
            content: "";
            position: absolute;
            inset: 0;
            background:
                radial-gradient(circle at 50% 50%, rgba(255, 255, 255, .2), transparent 34%),
                linear-gradient(120deg, transparent 44%, rgba(255, 255, 255, .7) 50%, transparent 56%);
            transform: translateX(-140%) rotate(12deg);
            animation: sheen 8s ease-in-out infinite;
            pointer-events: none;
            mix-blend-mode: screen;
        }.sc-tw .amber-button:hover{
            transform: translateY(-3px);
            box-shadow:
                inset 0 1px 0 rgba(255, 255, 255, .5),
                0 30px 60px rgba(0, 0, 0, .3);
        }.sc-tw .section-shell{
            width: min(1680px, calc(100% - 28px));
            margin: 0 auto;
        }.sc-tw .top-rail{
            position: fixed;
            inset: 18px 18px auto 18px;
            z-index: 80;
            display: grid;
            grid-template-columns: auto 1fr auto;
            gap: 16px;
            align-items: center;
            padding: 14px 16px;
            border: 1px solid rgba(255, 255, 255, .08);
            background: rgba(15, 17, 20, .72);
            backdrop-filter: blur(20px);
            -webkit-backdrop-filter: blur(20px);
            box-shadow: 0 18px 60px rgba(0, 0, 0, .26);
        }.sc-tw .brand{
            display: flex;
            align-items: center;
            gap: 14px;
            min-width: 0;
        }.sc-tw .brand-mark{
            width: 40px;
            height: 40px;
            display: grid;
            place-items: center;
            border-radius: 3px;
            border: 1px solid rgba(255, 255, 255, .08);
            background: rgba(255, 255, 255, .05);
        }.sc-tw .brand-copy{
            min-width: 0;
            line-height: 1.02;
        }.sc-tw .brand-copy .k{
            font-size: 10px;
            letter-spacing: .34em;
            text-transform: uppercase;
            color: rgba(255, 255, 255, .56);
        }.sc-tw .brand-copy .v{
            margin-top: 4px;
            font-size: 14px;
            color: rgba(255, 255, 255, .88);
        }.sc-tw .rail-nav{
            display: flex;
            justify-content: center;
            gap: 20px;
            overflow-x: auto;
            scrollbar-width: none;
            text-transform: uppercase;
            letter-spacing: .24em;
            font-size: 10px;
            color: rgba(255, 255, 255, .6);
        }.sc-tw .rail-nav::-webkit-scrollbar{
            display: none;
        }.sc-tw .rail-nav a{
            color: inherit;
            text-decoration: none;
            white-space: nowrap;
            transition: .25s ease;
        }.sc-tw .rail-nav a:hover{
            color: var(--amber);
        }.sc-tw .top-stats{
            display: flex;
            align-items: center;
            gap: 14px;
        }.sc-tw .meter{
            width: 220px;
            height: 8px;
            background: rgba(255, 255, 255, .08);
            overflow: hidden;
            border-radius: 2px;
        }.sc-tw .meter span{
            display: block;
            width: 74%;
            height: 100%;
            background: linear-gradient(90deg, rgba(255, 201, 118, .95), rgba(172, 115, 43, .95));
        }.sc-tw .hero{
            min-height: 100svh;
            position: relative;
            overflow: hidden;
            padding-top: 88px;
        }.sc-tw .hero-grid{
            width: min(1680px, calc(100% - 28px));
            margin: 0 auto;
            min-height: calc(100svh - 88px);
            display: grid;
            grid-template-columns: repeat(12, 1fr);
            gap: 14px;
            align-items: stretch;
        }.sc-tw .telemetry{
            position: absolute;
            z-index: 5;
            width: clamp(220px, 18vw, 320px);
            padding: 14px 16px;
            border-radius: 3px;
            border: 1px solid rgba(255, 195, 126, .28);
            background: rgba(20, 20, 20, .42);
            backdrop-filter: blur(20px);
            -webkit-backdrop-filter: blur(20px);
            box-shadow: 0 18px 48px rgba(0, 0, 0, .24);
        }.sc-tw .telemetry .k{
            text-transform: uppercase;
            letter-spacing: .3em;
            font-size: 10px;
            color: rgba(255, 255, 255, .56);
        }.sc-tw .telemetry .v{
            margin-top: 10px;
            font-size: clamp(2rem, 3vw, 3rem);
            line-height: 1;
            letter-spacing: -.06em;
            color: white;
        }.sc-tw .telemetry .d{
            margin-top: 8px;
            color: rgba(255, 255, 255, .72);
            line-height: 1.7;
            font-size: 12px;
        }.sc-tw .hero-core{
            grid-column: 3 / span 8;
            align-self: center;
            position: relative;
            z-index: 3;
            padding: 22px;
            border-radius: 2.4rem;
            background:
                linear-gradient(180deg, rgba(255, 255, 255, .06), rgba(255, 255, 255, .02)),
                linear-gradient(135deg, rgba(255, 193, 127, .06), transparent 42%);
            box-shadow: 0 30px 90px rgba(0, 0, 0, .36);
        }.sc-tw .core-shell{
            position: relative;
            overflow: hidden;
            border-radius: 2rem;
            border: 1px solid rgba(255, 199, 137, .2);
            background: rgba(20, 20, 20, .55);
            box-shadow:
                inset 0 1px 0 rgba(255, 255, 255, .08),
                0 0 0 1px rgba(255, 255, 255, .03);
        }.sc-tw .core-shell::before{
            content: "";
            position: absolute;
            inset: -2px;
            background:
                radial-gradient(circle at center, rgba(255, 196, 116, .28), transparent 36%),
                radial-gradient(circle at center, rgba(255, 255, 255, .08), transparent 56%);
            pointer-events: none;
            opacity: .9;
        }.sc-tw .core-shell::after{
            content: "";
            position: absolute;
            inset: 0;
            background:
                linear-gradient(180deg, rgba(255, 255, 255, .08), transparent 22%),
                linear-gradient(90deg, rgba(255, 255, 255, .04), transparent 24%, transparent 76%, rgba(255, 255, 255, .04));
            pointer-events: none;
            mix-blend-mode: screen;
        }.sc-tw .hero-video{
            width: 100%;
            height: clamp(36rem, 64vh, 54rem);
            object-fit: cover;
            display: block;
            transform: scale(1.05);
            filter: saturate(1.08) contrast(1.06) brightness(.94);
            mask-image: linear-gradient(180deg, black 0 100%);
            -webkit-mask-image: linear-gradient(180deg, black 0 100%);
            will-change: transform;
        }.sc-tw .shimmer-frame{
            position: absolute;
            inset: 0;
            border-radius: 2rem;
            pointer-events: none;
            box-shadow:
                inset 0 0 0 1px rgba(255, 201, 118, .28),
                inset 0 0 80px rgba(255, 196, 116, .22),
                0 0 80px rgba(255, 178, 92, .1);
        }.sc-tw .hero-title{
            position: absolute;
            left: 50%;
            top: 50%;
            transform: translate(-50%, -50%);
            z-index: 8;
            width: min(1020px, 92%);
            text-align: center;
            padding: 20px 24px;
        }.sc-tw .hero-title h1{
            font-size: clamp(4rem, 9vw, 8.8rem);
            line-height: .84;
            letter-spacing: -.08em;
            color: white;
            text-shadow: 0 16px 40px rgba(0, 0, 0, .34);
        }.sc-tw .hero-title p{
            margin-top: 18px;
            font-size: 16px;
            line-height: 1.9;
            color: rgba(255, 255, 255, .8);
            max-width: 760px;
            margin-inline: auto;
        }.sc-tw .hero-title .actions{
            margin-top: 26px;
            display: flex;
            justify-content: center;
            flex-wrap: wrap;
            gap: 12px;
        }.sc-tw .hero-title .actions button{
            height: 54px;
            padding: 0 22px;
            border: none;
            cursor: pointer;
            text-transform: uppercase;
            letter-spacing: .26em;
            font-size: 10px;
        }.sc-tw .hero-title .chips{
            margin-top: 18px;
            display: flex;
            flex-wrap: wrap;
            justify-content: center;
            gap: 10px;
        }.sc-tw .hero-title .chips span{
            padding: 10px 12px;
            border-radius: 999px;
            background: rgba(255, 255, 255, .08);
            border: 1px solid rgba(255, 255, 255, .08);
            color: rgba(255, 255, 255, .74);
            text-transform: uppercase;
            letter-spacing: .2em;
            font-size: 10px;
        }.sc-tw .glow-left,.sc-tw .glow-right{
            position: absolute;
            top: 50%;
            width: 20%;
            height: 42%;
            pointer-events: none;
            transform: translateY(-50%);
            filter: blur(22px);
            opacity: .9;
        }.sc-tw .glow-left{
            left: 0;
            background: radial-gradient(circle, rgba(255, 193, 98, .22), transparent 68%);
        }.sc-tw .glow-right{
            right: 0;
            background: radial-gradient(circle, rgba(255, 255, 255, .09), transparent 68%);
        }.sc-tw .section{
            position: relative;
            margin-top: -22px;
            padding: 120px 0;
        }.sc-tw .section-shell{
            width: min(1680px, calc(100% - 28px));
            margin: 0 auto;
        }.sc-tw .section-heading{
            display: flex;
            justify-content: space-between;
            gap: 20px;
            align-items: flex-end;
            margin-bottom: 26px;
        }.sc-tw .section-heading h2{
            font-size: clamp(3rem, 6vw, 6.2rem);
            line-height: .88;
            letter-spacing: -.08em;
            color: white;
        }.sc-tw .section-heading p{
            max-width: 460px;
            color: rgba(255, 255, 255, .68);
            line-height: 1.95;
        }.sc-tw .section-heading .tag{
            text-transform: uppercase;
            letter-spacing: .34em;
            font-size: 10px;
            color: rgba(255, 255, 255, .52);
            margin-bottom: 18px;
        }.sc-tw .blueprint{
            position: relative;
            overflow: hidden;
            border-top: 1px solid rgba(255, 255, 255, .08);
            border-bottom: 1px solid rgba(255, 255, 255, .08);
            background:
                linear-gradient(180deg, rgba(48, 49, 55, .96), rgba(28, 30, 35, .98));
            box-shadow: 0 28px 90px rgba(0, 0, 0, .26);
            z-index: 3;
        }.sc-tw .blueprint-grid{
            display: grid;
            grid-template-columns: repeat(12, 1fr);
            gap: 12px;
            padding: 14px;
        }.sc-tw .tile{
            position: relative;
            overflow: hidden;
            min-height: 180px;
            border: 1px solid rgba(255, 255, 255, .08);
            background:
                linear-gradient(180deg, rgba(255, 255, 255, .05), rgba(255, 255, 255, .02));
            box-shadow: 0 16px 44px rgba(0, 0, 0, .18);
        }.sc-tw .tile::before{
            content: "";
            position: absolute;
            inset: 0;
            background:
                linear-gradient(180deg, rgba(255, 255, 255, .04), transparent 28%),
                repeating-linear-gradient(90deg, rgba(255, 255, 255, .05) 0 1px, transparent 1px 18px);
            opacity: .16;
            pointer-events: none;
        }.sc-tw .tile .inner{
            position: relative;
            z-index: 2;
            height: 100%;
            padding: 18px;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            gap: 18px;
        }.sc-tw .tile .label{
            text-transform: uppercase;
            letter-spacing: .3em;
            font-size: 10px;
            color: rgba(255, 255, 255, .54);
        }.sc-tw .tile h3{
            font-size: clamp(1.7rem, 3vw, 3.3rem);
            line-height: .92;
            letter-spacing: -.05em;
            color: white;
        }.sc-tw .tile p{
            color: rgba(255, 255, 255, .72);
            line-height: 1.9;
            max-width: 36ch;
        }.sc-tw .tile .mini{
            display: flex;
            justify-content: space-between;
            gap: 14px;
            align-items: flex-end;
            font-family: "IBM Plex Mono", monospace;
            text-transform: uppercase;
            letter-spacing: .24em;
            font-size: 10px;
            color: rgba(255, 255, 255, .5);
        }.sc-tw .tile .metric{
            font-size: 42px;
            line-height: 1;
            letter-spacing: -.06em;
            color: #fff;
        }.sc-tw .tile.a{
            grid-column: span 5;
            min-height: 220px;
        }.sc-tw .tile.b{
            grid-column: span 4;
            min-height: 220px;
        }.sc-tw .tile.c{
            grid-column: span 3;
            min-height: 220px;
        }.sc-tw .tile.d{
            grid-column: span 4;
            min-height: 260px;
        }.sc-tw .tile.e{
            grid-column: span 8;
            min-height: 260px;
        }.sc-tw .tile.f{
            grid-column: span 6;
            min-height: 190px;
        }.sc-tw .tile.g{
            grid-column: span 6;
            min-height: 190px;
        }.sc-tw .material-anatomy{
            position: relative;
            overflow: hidden;
            background:
                radial-gradient(circle at 12% 10%, rgba(255, 190, 110, .12), transparent 16%),
                linear-gradient(180deg, rgba(20, 21, 24, .96), rgba(10, 11, 13, 1));
            z-index: 2;
            border-top: 1px solid rgba(255, 255, 255, .08);
            border-bottom: 1px solid rgba(255, 255, 255, .08);
        }.sc-tw .anatomy-shell{
            width: min(1680px, calc(100% - 28px));
            margin: 0 auto;
            padding: 36px 0 42px;
        }.sc-tw .anatomy-head{
            display: flex;
            justify-content: space-between;
            gap: 20px;
            align-items: flex-end;
            margin-bottom: 22px;
            padding-inline: 2px;
        }.sc-tw .anatomy-head h2{
            font-size: clamp(3rem, 6vw, 6rem);
            line-height: .88;
            letter-spacing: -.08em;
            color: white;
        }.sc-tw .anatomy-head p{
            max-width: 460px;
            color: rgba(255, 255, 255, .68);
            line-height: 1.95;
        }.sc-tw .anatomy-stage{
            display: grid;
            grid-template-columns: 1.1fr .9fr;
            gap: 16px;
            align-items: stretch;
        }.sc-tw .wall-view{
            position: relative;
            overflow: hidden;
            border: 1px solid rgba(255, 255, 255, .08);
            background:
                linear-gradient(180deg, rgba(255, 255, 255, .05), rgba(255, 255, 255, .02)),
                linear-gradient(135deg, rgba(255, 190, 108, .08), transparent 40%);
            min-height: 720px;
            padding: 22px;
            box-shadow: 0 22px 60px rgba(0, 0, 0, .25);
        }.sc-tw .cross-section{
            position: absolute;
            inset: 22px;
            border-radius: 3px;
            background:
                linear-gradient(90deg, rgba(224, 198, 167, .14) 0 16%, rgba(150, 142, 135, .14) 16% 33%, rgba(74, 73, 78, .16) 33% 54%, rgba(109, 92, 70, .16) 54% 76%, rgba(222, 183, 115, .18) 76% 100%),
                linear-gradient(180deg, rgba(255, 255, 255, .04), rgba(255, 255, 255, .015));
            overflow: hidden;
            border: 1px solid rgba(255, 255, 255, .08);
        }.sc-tw .cross-section .layer{
            position: absolute;
            left: 0;
            right: 0;
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 0 22px;
            border-top: 1px solid rgba(255, 255, 255, .08);
            border-bottom: 1px solid rgba(0, 0, 0, .12);
            font-family: "IBM Plex Mono", monospace;
            text-transform: uppercase;
            letter-spacing: .22em;
            font-size: 10px;
            color: rgba(255, 255, 255, .78);
            transition: transform .4s ease, opacity .4s ease;
        }.sc-tw .cross-section .layer.active{
            transform: translateX(8px);
            opacity: 1;
        }.sc-tw .cross-section .layer span:last-child{
            color: rgba(255, 255, 255, .55);
        }.sc-tw .cross-section .l1{
            top: 0;
            height: 15%;
            background: rgba(208, 169, 122, .28);
        }.sc-tw .cross-section .l2{
            top: 15%;
            height: 16%;
            background: rgba(126, 111, 92, .24);
        }.sc-tw .cross-section .l3{
            top: 31%;
            height: 18%;
            background: rgba(43, 54, 60, .28);
        }.sc-tw .cross-section .l4{
            top: 49%;
            height: 17%;
            background: rgba(99, 82, 58, .26);
        }.sc-tw .cross-section .l5{
            top: 66%;
            height: 18%;
            background: rgba(210, 171, 97, .26);
        }.sc-tw .cross-section .l6{
            top: 84%;
            height: 16%;
            background: rgba(255, 255, 255, .06);
        }.sc-tw .cross-overlay{
            position: absolute;
            inset: auto 22px 22px 22px;
            padding: 16px 18px;
            border: 1px solid rgba(255, 193, 119, .22);
            background: rgba(17, 17, 19, .52);
            backdrop-filter: blur(20px);
            -webkit-backdrop-filter: blur(20px);
            color: white;
        }.sc-tw .cross-overlay .k{
            text-transform: uppercase;
            letter-spacing: .3em;
            font-size: 10px;
            color: rgba(255, 255, 255, .58);
        }.sc-tw .cross-overlay .v{
            margin-top: 10px;
            font-size: clamp(1.8rem, 3vw, 3rem);
            line-height: 1;
            letter-spacing: -.06em;
        }.sc-tw .anatomy-copy{
            display: flex;
            flex-direction: column;
            gap: 16px;
        }.sc-tw .detail-card{
            padding: 20px;
            min-height: calc(33.33% - 10px);
            border: 1px solid rgba(255, 255, 255, .08);
            background:
                linear-gradient(180deg, rgba(255, 255, 255, .05), rgba(255, 255, 255, .015));
            box-shadow: 0 18px 44px rgba(0, 0, 0, .22);
        }.sc-tw .detail-card .k{
            text-transform: uppercase;
            letter-spacing: .28em;
            font-size: 10px;
            color: rgba(255, 255, 255, .54);
        }.sc-tw .detail-card .v{
            margin-top: 12px;
            font-size: clamp(1.7rem, 3.5vw, 3rem);
            line-height: .95;
            letter-spacing: -.06em;
        }.sc-tw .detail-card p{
            margin-top: 12px;
            color: rgba(255, 255, 255, .68);
            line-height: 1.85;
        }.sc-tw .portfolio{
            position: relative;
            z-index: 4;
            background:
                radial-gradient(circle at top left, rgba(255, 198, 116, .1), transparent 16%),
                linear-gradient(180deg, rgba(31, 29, 28, 1), rgba(20, 19, 18, 1));
            padding: 120px 0;
        }.sc-tw .portfolio-shell{
            width: min(1680px, calc(100% - 28px));
            margin: 0 auto;
        }.sc-tw .portfolio-head{
            display: flex;
            justify-content: space-between;
            gap: 20px;
            align-items: flex-end;
            margin-bottom: 24px;
        }.sc-tw .portfolio-head h2{
            font-size: clamp(3rem, 6vw, 6rem);
            line-height: .88;
            letter-spacing: -.08em;
            color: white;
        }.sc-tw .portfolio-head p{
            max-width: 470px;
            color: rgba(255, 255, 255, .68);
            line-height: 1.95;
        }.sc-tw .monoliths{
            display: grid;
            gap: 16px;
        }.sc-tw .monolith{
            position: relative;
            overflow: hidden;
            border: 1px solid rgba(255, 255, 255, .08);
            background:
                linear-gradient(180deg, rgba(255, 255, 255, .04), rgba(255, 255, 255, .015)),
                linear-gradient(135deg, rgba(255, 200, 120, .06), transparent 42%);
            box-shadow: 0 26px 80px rgba(0, 0, 0, .26);
            min-height: 290px;
            transition: transform .5s cubic-bezier(.16, 1, .3, 1), border-color .35s ease;
        }.sc-tw .monolith:hover{
            transform: translateY(-3px);
            border-color: rgba(255, 200, 120, .16);
        }.sc-tw .monolith .bg{
            position: absolute;
            inset: 0;
            opacity: .96;
            background-size: cover;
            background-position: center;
            filter: saturate(1.02) contrast(1.04) brightness(.86);
        }.sc-tw .monolith .veil{
            position: absolute;
